def test_cli_static_only_detects_fixture_and_fails_nonzero(tmp_path):
    root = _fake_repo(tmp_path, {"vendor/pdf2zh_next/__init__.py": ""})
    result = _run_static(root)
    assert result.returncode == 1
    assert "UPGRADE GOVERNANCE GATE FAILED" in result.stdout
    assert "shadow package directory" in result.stdout
    assert "PASSED" not in result.stdout


def test_cli_static_only_passes_on_real_repo():
    result = _run_static(REPO_ROOT)
    assert result.returncode == 0, result.stderr
    assert "Upgrade governance gate PASSED" in result.stdout


def test_contract_selection_covers_required_invariants():
    gate = _load_gate()
    assert gate.CONTRACT_TEST_FILES == [
        "tests/test_dependency_contract.py",
        "tests/test_upstream_contract.py",
        "tests/test_upstream_boundary_governance.py",
        "tests/test_strict_glossary.py",
        "tests/test_glossary_compliance_flow.py",
        "tests/test_terminology_compliance.py",
        "tests/test_glossary_compiler.py",
        "tests/release/test_portable_processes.py",
    ]
    for rel in gate.CONTRACT_TEST_FILES:
        assert (REPO_ROOT / rel).is_file(), f"gate contract test missing: {rel}"


def test_verify_script_invokes_static_gate_and_ci_runs_verify():
    verify = (REPO_ROOT / "scripts" / "verify.ps1").read_text(encoding="utf-8")
    assert "upgrade_governance_gate.py" in verify
    assert "--static-only" in verify
    assert "Upgrade governance gate" in verify
    ci = (REPO_ROOT / ".github" / "workflows" / "ci.yml").read_text(encoding="utf-8")
    assert "scripts/verify.ps1" in ci


def test_docs_record_gate_command_and_scope():
    dep_upgrade = (REPO_ROOT / "docs" / "governance" / "dependency-upgrade.md").read_text(encoding="utf-8")
    readme = (REPO_ROOT / "README.md").read_text(encoding="utf-8")
    architecture = (REPO_ROOT / "docs" / "architecture.md").read_text(encoding="utf-8")
    for text in (dep_upgrade, readme):
        assert "python scripts/upgrade_governance_gate.py" in text
    for text in (dep_upgrade, architecture):
        assert "upgrade_governance_gate.py" in text
    assert "--static-only" in dep_upgrade
    assert "P2-04" in architecture


def test_gate_script_does_not_self_match_markers():
    text = GATE.read_text(encoding="utf-8")
    for marker in (
        "class " + "AutomaticTermExtractor" + ":",
        "class " + "SharedContextCrossSplitPart" + ":",
    ):
        assert marker not in text


@pytest.mark.skipif(os.name != "nt", reason="verify.ps1 is Windows/PowerShell-only")
def test_verify_full_script_accepts_static_gate_invocation(tmp_path):
    """verify.ps1 的全量 fake 运行路径必须兼容新增的静态治理门步骤。"""
    fake = tmp_path / "fake-bin"

    def write_cmd(path: Path, body: str) -> None:
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(body.replace("\n", "\r\n"), encoding="ascii")

    write_cmd(
        fake / "python.cmd",
        "@echo off\n@echo %~f0\n@echo 3.12.0\nexit /b 0\n",
    )
    write_cmd(fake / "npm.cmd", "@echo off\necho fake npm %*\nexit /b 0\n")
    env = os.environ.copy()
    env["PATH"] = str(fake) + os.pathsep + env["PATH"]
    env.pop("PYTHONPATH", None)
    result = subprocess.run(
        [
            "powershell",
            "-NoProfile",
            "-ExecutionPolicy",
            "Bypass",
            "-File",
            str(REPO_ROOT / "scripts" / "verify.ps1"),
            "-PythonExecutable",
            str(fake / "python.cmd"),
        ],
        cwd=REPO_ROOT,
        env=env,
        capture_output=True,
        text=True,
        timeout=120,
    )
    assert result.returncode == 0, result.stderr
    assert "Upgrade governance gate" in result.stdout
